package main

// ❌ OLD: Allocating a fresh 32KB buffer per call, in a high-QPS
// handler, creates heavy allocation churn: each buffer must be
// allocated, zeroed, scanned by the GC (as a large object), and
// collected. Under load this shows up as GC CPU and latency spikes.
func handle(r io.Reader) error {
	buf := make([]byte, 32*1024) // ❌ OLD: alloc per request
	_, err := io.ReadFull(r, buf)
	if err != nil {
		return err
	}
	return process(buf)
}

// process(buf) may itself retain buf — but here it's used and
// discarded, so its allocation was pure overhead.

