package main

import "sync"

// ✅ NEW: Buffers are reused across calls. Get() returns a pooled
// buffer or New() if empty; Put() returns it for the next caller.
// The pool reduces allocation rate dramatically at high QPS.
var bufPool = sync.Pool{
	New: func() any {
		b := make([]byte, 32*1024)
		return &b // ✅ NEW: pointer to keep the slice header stable
	},
}

func handle(r io.Reader) error {
	buf := bufPool.Get().(*[]byte) // ✅ NEW: reuse (or New if drained)
	defer bufPool.Put(buf)         // ✅ NEW: return for reuse

	_, err := io.ReadFull(r, *buf)
	if err != nil {
		return err
	}
	return process(*buf)
}

// ⚠️ Pool objects may be dropped by GC at any time — Get() returning
// nil is expected; New covers it. Never rely on pooled state
// surviving between Put and Get across a GC.
